#!/bin/sh
set -eu
share="/Volumes/My Shared Files/ClaudeShield-Exchange"
[ -d "$share/01_在研课题_Projects" ] || { echo "请在已挂载交换卷的 macOS 客机执行"; exit 1; }
python3 - "$share" <<'PY'
import base64, hashlib, os, re, shutil, subprocess, sys, tempfile
from pathlib import Path

share = Path(sys.argv[1])
dest = Path.home() / "Library/Application Support/Claude"
payloads = {
    "state_client.py": base64.b64decode(''),
    "mcp_filesystem_server.py": base64.b64decode(''),
}

if dest.is_dir():
    backup = Path(tempfile.mkdtemp(dir=dest, prefix="pre-state-"))
    for name, body in payloads.items():
        compile(body, name, "exec")
        if (dest / name).exists():
            shutil.copy2(dest / name, backup / name)
        with tempfile.NamedTemporaryFile(dir=dest, delete=False) as f:
            f.write(body); f.flush(); os.fsync(f.fileno())
        os.replace(f.name, dest / name)
    print("[OK] 客机本地 MCP 与 state_client 已升级 ->", dest)

scripts_dir = share / "00_全局中枢_Hub/scripts"
for name, body in payloads.items():
    target = scripts_dir / name
    try:
        with open(target, "r+b") as wf:
            wf.seek(0); wf.write(body); wf.truncate(); wf.flush(); os.fsync(wf.fileno())
    except OSError:
        pass

def heal_file_from_cache(target: Path, snap: Path):
    sdata = snap.read_bytes()
    with open(target, "r+b") as wf:
        wf.seek(0); wf.write(sdata); wf.truncate(); wf.flush(); os.fsync(wf.fileno())
    vdata = target.read_bytes()
    return hashlib.sha256(vdata).hexdigest(), len(vdata), (b"\x00" in vdata)

for proj in sorted((share / "01_在研课题_Projects").glob("P*_*")):
    if not proj.is_dir(): continue
    st_file = proj / "_control/01_PROJECT_STATE.md"
    cache_dir = proj / "_control/.state_cache"
    if st_file.is_file() and cache_dir.is_dir():
        snaps = [cache_dir / n for n in os.listdir(cache_dir) if re.fullmatch(r"[a-f0-9]{64}\.md", n)]
        if snaps:
            latest = max(snaps, key=lambda x: x.stat().st_mtime_ns)
            sha, sz, has_nul = heal_file_from_cache(st_file, latest)
            print(f"[OK] {proj.name} 01_PROJECT_STATE.md 已从客机 VFS 刷入 -> sha256={sha[:16]}... ({sz}B, has_nul={has_nul})")
    for rel in ("_bus/reply.md", "05_Gitea协作同步区/ISSUES_DETAIL_INBOX.md", "05_Gitea协作同步区/PR_STATUS.md", "05_Gitea协作同步区/RELEASE_CLEANUP_LEDGER.tsv", "02_实验与验证/_inbox_copy/ISSUES_DETAIL_INBOX_copy.md", "02_实验与验证/_inbox_copy/GITEA_LATEST.md"):
        fp = proj / rel
        vdir = fp.parent / ".virtiofs_cache"
        if fp.is_file() and vdir.is_dir():
            cands = [vdir / n for n in os.listdir(vdir) if n.startswith(fp.name + ".") and n.endswith(".cache")]
            if cands:
                latest_c = max(cands, key=lambda x: x.stat().st_mtime_ns)
                sha, sz, has_nul = heal_file_from_cache(fp, latest_c)
                print(f"[OK] {proj.name} {rel} 已同步 -> sha256={sha[:16]}... ({sz}B)")

# 重启客机后台旧的 mcp_filesystem_server.py 进程，使新代码立即在内存中生效
subprocess.run(["pkill", "-f", "mcp_filesystem_server.py"], check=False)
print("[OK] 已终止旧 MCP 子进程（若 Claude Desktop 正在打开，建议按 Cmd+Q 重开一次 Claude Desktop 后开启新会话，无需重启虚拟机！）")
PY
